  function estimateNutritionForName(name){const n=String(name||'').toLocaleLowerCase('pt-BR').replace(/^(?:eu\s+)?(?:comi|consumi|acabei de comer|tomei|bebi)\s+/,'').trim();for(const [re,v] of commonFoodNutrition){if(re.test(n))return {name:v[0],kcal:v[1],protein:v[2],carbs:v[3],fat:v[4],source:'Tabela local de referência',notes:'Estimativa de composição média; pode variar conforme preparo e marca.'}}return null}
  function updateFoodNutritionEstimate(){const f=$('#foodForm');if(!f)return;const q=Number(f.elements.qty.value||0), kcal=Number(f.elements.kcal.value), protein=Number(f.elements.protein.value), carbs=Number(f.elements.carbs.value), fat=Number(f.elements.fat.value);const box=$('#foodNutritionEstimate');if(!box)return;const hasAny=['kcal','protein','carbs','fat'].some(k=>f.elements[k].value!=='');if(!q||!hasAny){box.textContent='Informe alimento e quantidade para estimar automaticamente os nutrientes totais da porção.';return}const fmt=n=>Number.isFinite(n)?(n*q/100).toLocaleString('pt-BR',{maximumFractionDigits:1}):'—';box.innerHTML='<strong>Estimativa para '+q+' g/ml:</strong><br>'+fmt(kcal)+' kcal · Proteína '+fmt(protein)+' g · Carboidratos '+fmt(carbs)+' g · Gorduras '+fmt(fat)+' g';}
  async function autoFillFoodNutrition(name){const f=$('#foodForm');if(!f||!name.trim())return;const local=estimateNutritionForName(name);if(local){if(!f.elements.kcal.value)f.elements.kcal.value=local.kcal;if(!f.elements.protein.value)f.elements.protein.value=local.protein;if(!f.elements.carbs.value)f.elements.carbs.value=local.carbs;if(!f.elements.fat.value)f.elements.fat.value=local.fat;updateFoodNutritionEstimate();return}try{const url='https://world.openfoodfacts.org/cgi/search.pl?search_terms='+encodeURIComponent(name)+'&search_simple=1&action=process&json=1&page_size=5&fields=product_name,product_name_pt,nutriments';const res=await fetch(url,{headers:{'Accept':'application/json'}});if(!res.ok)return;const body=await res.json();const wanted=name.toLocaleLowerCase('pt-BR').replace(/^(?:eu\s+)?(?:comi|consumi|tomei|bebi)\s+/,'').trim();const product=(body.products||[]).find(p=>((p.product_name_pt||p.product_name||'').toLocaleLowerCase('pt-BR')).includes(wanted)||wanted.includes((p.product_name_pt||p.product_name||'').toLocaleLowerCase('pt-BR')));if(!product)return;const n=product.nutriments||{};if(!f.elements.kcal.value&&n['energy-kcal_100g']!=null)f.elements.kcal.value=n['energy-kcal_100g'];if(!f.elements.protein.value&&n.proteins_100g!=null)f.elements.protein.value=n.proteins_100g;if(!f.elements.carbs.value&&n.carbohydrates_100g!=null)f.elements.carbs.value=n.carbohydrates_100g;if(!f.elements.fat.value&&n.fat_100g!=null)f.elements.fat.value=n.fat_100g;const note=$('#foodNutritionEstimate');if(note)note.dataset.source='Open Food Facts';updateFoodNutritionEstimate()}catch{}}
  function parseFoodEntry(raw,qtyRaw){
    let text=String(raw||'').trim(), lower=text.toLocaleLowerCase('pt-BR');
    const out={name:text,qty:qtyRaw===''||qtyRaw==null?'':Number(qtyRaw),kcal:'',protein:'',carbs:'',fat:'',source:'manual-estimate',notes:'Estimativa automática por texto; confira a porção e o rótulo.'};
    const kit=/kit\s?-?\s?kat|kitkat/.test(lower), banana=/banana/.test(lower), apple=/maçã|maca/.test(lower), bread=/pão francês|pao frances|pãozinho/.test(lower), rice=/arroz cozido|arroz branco/.test(lower), egg=/ovo cozido|ovo/.test(lower), chicken=/frango|peito de frango/.test(lower);
    let amount=1; const m=lower.match(/\b(\d+(?:[.,]\d+)?)\b/); if(m) amount=Number(m[1].replace(',','.'))||1; if(/fileira.*3\s*(?:tabletes|dedos|fingers)|3\s*(?:tabletes|dedos|fingers).*kit/.test(lower)) amount=1;
    if(kit){
      let grams=41.5;
      if(/fileira|3\s*(?:tabletes|dedos|fingers)|tr[eê]s\s*(?:tabletes|dedos|fingers)/.test(lower)) grams=31;
      else if(/tablete|finger|dedo/.test(lower)&&!/(inteiro|todo|pacote|barra inteira)/.test(lower)) grams=10.3;
      else if(/meio|metade/.test(lower)) grams=20.75;
      else if(/pacote|2\s*(?:kitkat|barras)/.test(lower)) grams=82;
      out.qty=out.qty||Math.max(1,Math.round(grams*amount*10)/10);out.name='KitKat';out.kcal=518;out.protein=6.3;out.carbs=61;out.fat=27;
    } else if(banana){
      out.qty=out.qty||Math.max(1,Math.round(90*amount));out.name='Banana (média)';out.kcal=89;out.protein=1.1;out.carbs=22.8;out.fat=0.3;
    } else if(apple||bread||rice||egg||chicken){
      const presets=apple?{name:'Maçã (média)',grams:180,kcal:52,protein:0.3,carbs:13.8,fat:0.2}:bread?{name:'Pão francês',grams:50,kcal:300,protein:9,carbs:58,fat:3.1}:rice?{name:'Arroz branco cozido',grams:160,kcal:130,protein:2.7,carbs:28.2,fat:0.3}:egg?{name:'Ovo',grams:50,kcal:155,protein:13,carbs:1.1,fat:11}:{name:'Frango cozido (peito)',grams:100,kcal:165,protein:31,carbs:0,fat:3.6};
      out.qty=out.qty||Math.max(1,Math.round(presets.grams*amount));out.name=presets.name;out.kcal=presets.kcal;out.protein=presets.protein;out.carbs=presets.carbs;out.fat=presets.fat;
    } else {
      // Extract conversational wrappers while preserving the food name.
      out.name=text.replace(/^(?:eu\s+)?(?:comi|consumi|acabei de comer|tomei|bebi)\s+/i,'').replace(/^\d+(?:[.,]\d+)?\s*(?:unidades?\s+de\s+)?/i,'').trim()||text;
      if(!out.qty) out.qty='';
      out.source='manual';out.notes='';
    }
    return out;
  }
